# A posted goods receipt never changes, except that cost-pending lines gain their cost once
# ("complete costs", ADR-041). Draft receipts and their lines are freely editable.
INWARD_GUARD_SQL = """
CREATE FUNCTION inventory_inward_guard() RETURNS trigger AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        IF OLD.status = 'POSTED' THEN
            RAISE EXCEPTION 'posted goods receipt % cannot be deleted', OLD.number
            USING ERRCODE = 'restrict_violation';
        END IF;
        RETURN OLD;
    END IF;
    IF OLD.status = 'POSTED' AND
       (to_jsonb(NEW) - 'total_cost' - 'cost_pending_lines' - 'updated_at')
       IS DISTINCT FROM (to_jsonb(OLD) - 'total_cost' - 'cost_pending_lines' - 'updated_at') THEN
        RAISE EXCEPTION 'posted goods receipt % cannot be changed', OLD.number
            USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN NEW;
END $$ LANGUAGE plpgsql;
CREATE TRIGGER inward_guard BEFORE UPDATE OR DELETE ON inventory_stockinward
    FOR EACH ROW EXECUTE FUNCTION inventory_inward_guard();

CREATE FUNCTION inventory_inward_line_guard() RETURNS trigger AS $$
DECLARE
    parent_status text;
    cost_cols text[] := ARRAY['unit_cost', 'line_cost', 'cost_status', 'cost_completed_at',
                              'cost_completed_by_id', 'updated_at'];
BEGIN
    SELECT status INTO parent_status FROM inventory_stockinward
        WHERE id = COALESCE(NEW.inward_id, OLD.inward_id);
    IF parent_status IS DISTINCT FROM 'POSTED' THEN
        RETURN COALESCE(NEW, OLD);
    END IF;
    IF TG_OP = 'UPDATE' AND OLD.cost_status = 'PENDING' AND NEW.cost_status = 'SET'
       AND (to_jsonb(NEW) - cost_cols) = (to_jsonb(OLD) - cost_cols) THEN
        RETURN NEW;
    END IF;
    RAISE EXCEPTION 'lines of a posted goods receipt cannot be changed (%)', TG_OP
            USING ERRCODE = 'restrict_violation';
END $$ LANGUAGE plpgsql;
CREATE TRIGGER inward_line_guard BEFORE INSERT OR UPDATE OR DELETE ON inventory_stockinwardline
    FOR EACH ROW EXECUTE FUNCTION inventory_inward_line_guard();
"""

