def backfill_warehouses_and_levels(apps, schema_editor):
    """Every existing tenant gets its default warehouse, and every product a zero stock level."""
    Tenant = apps.get_model("platform", "Tenant")
    Product = apps.get_model("catalog", "Product")
    Warehouse = apps.get_model("inventory", "Warehouse")
    StockLevel = apps.get_model("inventory", "StockLevel")
    for tenant_id in Tenant.objects.values_list("id", flat=True):
        warehouse = Warehouse.objects.filter(tenant_id=tenant_id, is_default=True).first()
        if warehouse is None:
            warehouse = Warehouse.objects.create(
                tenant_id=tenant_id,
                code=DEFAULT_WAREHOUSE_CODE,
                name=DEFAULT_WAREHOUSE_NAME,
                is_default=True,
            )
        StockLevel.objects.bulk_create(
            [
                StockLevel(tenant_id=tenant_id, product_id=product_id, warehouse=warehouse)
                for product_id in Product.objects.filter(tenant_id=tenant_id).values_list(
                    "id", flat=True
                )
            ],
            ignore_conflicts=True,
            batch_size=1000,
        )


